-- Phase 2: identity, sessions, tenancy and the audit log (docs/platform/04-database-design.md).
-- IDs are UUIDv7 generated by the API. Secrets are never stored: passwords as Argon2id PHC
-- strings, refresh tokens as SHA-256 hashes.

create table users (
    id            uuid primary key,
    email         text not null check (length(email) between 3 and 254),
    display_name  text not null check (length(display_name) between 1 and 100),
    password_hash text not null,
    status        text not null default 'active' check (status in ('active', 'locked', 'deleted')),
    created_at    timestamptz not null default now(),
    updated_at    timestamptz not null default now()
);
create unique index users_email_key on users (lower(email));

create table devices (
    id           uuid primary key,
    user_id      uuid not null references users (id) on delete cascade,
    kind         text not null check (kind in ('web', 'android')),
    name         text not null check (length(name) between 1 and 100),
    created_at   timestamptz not null default now(),
    last_seen_at timestamptz not null default now()
);
create index devices_user_idx on devices (user_id);

create table sessions (
    id                uuid primary key,
    user_id           uuid not null references users (id) on delete cascade,
    device_id         uuid not null references devices (id) on delete cascade,
    created_at        timestamptz not null default now(),
    last_refreshed_at timestamptz not null default now(),
    expires_at        timestamptz not null,
    revoked_at        timestamptz,
    revoke_reason     text check (revoke_reason in ('logout', 'revoked_by_user', 'refresh_reuse', 'admin'))
);
create index sessions_user_active_idx on sessions (user_id) where revoked_at is null;

-- One row per refresh token ever issued. A token is used once; presenting a used token again
-- revokes its session (rotation with reuse detection).
create table refresh_tokens (
    token_hash bytea primary key check (length(token_hash) = 32),
    session_id uuid not null references sessions (id) on delete cascade,
    created_at timestamptz not null default now(),
    used_at    timestamptz
);
create index refresh_tokens_session_idx on refresh_tokens (session_id);

create table workspaces (
    id         uuid primary key,
    name       text not null check (length(name) between 1 and 100),
    slug       text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'),
    created_by uuid references users (id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create table workspace_members (
    workspace_id uuid not null references workspaces (id) on delete cascade,
    user_id      uuid not null references users (id) on delete cascade,
    role         text not null check (role in ('owner', 'admin', 'maintainer', 'editor', 'viewer')),
    created_at   timestamptz not null default now(),
    primary key (workspace_id, user_id)
);
create index workspace_members_user_idx on workspace_members (user_id, workspace_id);

create table projects (
    id           uuid primary key,
    workspace_id uuid not null references workspaces (id) on delete cascade,
    name         text not null check (length(name) between 1 and 100),
    kind         text not null check (kind in ('code', 'analysis', 'rebuild')),
    deep_mode    boolean not null default false,
    created_by   uuid references users (id) on delete set null,
    created_at   timestamptz not null default now(),
    updated_at   timestamptz not null default now(),
    archived_at  timestamptz
);
create index projects_workspace_idx on projects (workspace_id, id);

-- Append-only history. No foreign keys on purpose: entries outlive the rows they describe.
create table audit_logs (
    id            bigint generated always as identity primary key,
    workspace_id  uuid,
    actor_user_id uuid,
    action        text not null,
    target_kind   text not null,
    target_id     uuid,
    request_id    uuid,
    ip_hash       text,
    details       jsonb not null default '{}'::jsonb,
    created_at    timestamptz not null default now()
);
create index audit_logs_workspace_idx on audit_logs (workspace_id, created_at desc);
create index audit_logs_actor_idx on audit_logs (actor_user_id, created_at desc);
